 const w=mnOf(s?.airdrop?.view?.mn||(typeof save!=='undefined'?save.mn:null)),P=plateStats(s?.airdrop?.view?.ap||(typeof save!=='undefined'?save.ap:null)),box=el('section','cq-plating','',d);
